import unittest

from solucao import tem_chave


class TestAChaveExiste(unittest.TestCase):
    def test_chave_que_esta(self):
        """tem_chave devolve True quando a chave esta"""
        self.assertTrue(tem_chave({"uva": 6, "kiwi": 3}, "kiwi"))

    def test_primeira_chave(self):
        """tem_chave devolve True para a primeira chave"""
        self.assertTrue(tem_chave({"uva": 6, "kiwi": 3}, "uva"))

    def test_chave_que_nao_esta(self):
        """tem_chave devolve False quando a chave nao esta"""
        self.assertFalse(tem_chave({"uva": 6, "kiwi": 3}, "pao"))

    def test_dicionario_vazio(self):
        """tem_chave devolve False para o dicionario vazio"""
        self.assertFalse(tem_chave({}, "uva"))
